CREATE OR REPLACE FUNCTION public.primeiro_util_mes(_data date) RETURNS date LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT date_trunc('month',_data)::date + CASE extract(dow FROM date_trunc('month',_data))::int WHEN 6 THEN 2 WHEN 0 THEN 1 ELSE 0 END; $$;
CREATE OR REPLACE FUNCTION public.mural_post_vigente(_publicado date,_hoje date) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT _publicado<=_hoje AND _hoje<public.primeiro_util_mes((_publicado+interval '1 month')::date); $$;
COMMENT ON COLUMN public.mural_posts.visivel_ate IS 'DEPRECATED: visibility derives from first weekday of the next publication month';
CREATE OR REPLACE FUNCTION public.pode_interagir_compilado(_aviso_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_user(auth.uid()) AND EXISTS(SELECT 1 FROM public.avisos a WHERE a.id=_aviso_id AND a.tipo IN ('compilado','insider') AND (public.aviso_vigente(a.publicar_em,a.expira_em,a.arquivado_em) OR public.gere_aviso(a.autor_id,a.perfil_id))); $$;
CREATE OR REPLACE FUNCTION public.mural_vigentes() RETURNS TABLE(id uuid,titulo text,texto text,imagem_path text,data_post date,tipo text,anos_casa integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.titulo,p.texto,p.imagem_path,p.data_post,p.tipo,p.anos_casa FROM public.mural_posts p WHERE public.is_active_user(auth.uid()) AND public.mural_post_vigente(p.data_post,(now() AT TIME ZONE 'America/Sao_Paulo')::date) ORDER BY p.data_post DESC,p.criado_em DESC LIMIT 8; $$;
CREATE OR REPLACE FUNCTION public.listar_mural() RETURNS TABLE(id uuid,titulo text,texto text,imagem_path text,data_post date,visivel_ate date,criado_em timestamptz,comentarios jsonb,tipo text,anos_casa integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.titulo,p.texto,p.imagem_path,p.data_post,p.visivel_ate,p.criado_em,coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'texto',c.texto,'criado_em',c.criado_em,'editado_em',c.editado_em,'usuario_id',c.usuario_id,'nome',coalesce(pr.full_name,pr.email,'Profissional')) ORDER BY c.criado_em) FROM public.mural_comentarios c LEFT JOIN public.profiles pr ON pr.id=c.usuario_id WHERE c.post_id=p.id),'[]'::jsonb),p.tipo,p.anos_casa FROM public.mural_posts p WHERE public.is_active_user(auth.uid()) AND public.mural_post_vigente(p.data_post,(now() AT TIME ZONE 'America/Sao_Paulo')::date) ORDER BY p.data_post DESC,p.criado_em DESC; $$;